# src/app.py - a minimal, production-shaped online endpoint
import os
from contextlib import asynccontextmanager

import joblib  # only for models YOU produced; prefer ONNX/safetensors for third-party artefacts
from fastapi import FastAPI
from pydantic import BaseModel, Field

state: dict = {}


@asynccontextmanager
async def lifespan(app: FastAPI):
    # Load once at startup, not per request: loading is the slow part (cold start).
    state["model"] = joblib.load(os.path.join(os.environ["MODEL_DIR"], "model.joblib"))
    state["version"] = os.environ.get("MODEL_VERSION", "unknown")
    yield
    state.clear()


app = FastAPI(lifespan=lifespan)


class Features(BaseModel):
    values: list[float] = Field(min_length=1, max_length=512)


@app.get("/healthz")
def healthz():
    return {"ok": "model" in state}


@app.post("/predict")
def predict(body: Features):
    score = float(state["model"].predict_proba([body.values])[0][1])
    return {"score": score, "model_version": state["version"]}

